-- Title: iam platform transfer ownership (S16 / EP-02 US-09)
-- Kind: patch
-- Intent: iam_platform_transfer_ownership
-- Touches: iam.transfer_platform_tenant_ownership
-- 8-B (2026-10-11): KI-08 — target must be an active member and must not own another tenant (BR-07, BR-32).
-- Promoted from _drafts/012_iam_platform_transfer_ownership.sql
-- Generated by tools/vet45_supabase_migrate/bin/promote_drafts.dart

create or replace function iam.transfer_platform_tenant_ownership(
  p_tenant_id uuid,
  p_new_owner_user_id uuid,
  p_expected_version integer,
  p_idempotency_key text
)
returns void
language plpgsql
security definer
set search_path = iam, pg_temp
as $$
declare
  v_status text;
  v_version int;
  v_fp text;
  v_existing iam.idempotency_records;
begin
  if not iam.has_platform_permission('platform.tenant.owner.transfer') then
    raise exception 'PLATFORM_PERMISSION_DENIED';
  end if;
  v_fp := p_tenant_id::text || '|' || p_new_owner_user_id::text || '|' || p_expected_version::text;
  v_existing := iam._idempotency_find('tenant.ownership.transfer', 'platform', p_idempotency_key, v_fp);
  if v_existing.idempotency_key is not null then
    return;
  end if;
  select coalesce(status, 'active'), coalesce(version, 1)
    into v_status, v_version
  from iam.tenants where id = p_tenant_id for update;
  if v_status = 'closed' then raise exception 'TENANT_STATE_INVALID'; end if;
  if v_version is distinct from p_expected_version then
    raise exception 'STATE_CHANGED';
  end if;
  -- BR-32: the target must be an active member of this tenant.
  if not exists (
    select 1 from iam.memberships m
    where m.tenant_id = p_tenant_id
      and m.user_id = p_new_owner_user_id
      and m.is_active
      and m.removed_at is null
  ) then
    raise exception 'OWNER_TARGET_INVALID';
  end if;
  -- BR-07 / KI-08: the target must not own another tenant (same predicate as
  -- iam._create_tenant_for_owner).
  if exists (
    select 1 from iam.memberships m
    where m.user_id = p_new_owner_user_id
      and m.tenant_id <> p_tenant_id
      and m.is_owner is true
      and m.removed_at is null
  ) then
    raise exception 'OWNER_TARGET_ALREADY_OWNER';
  end if;
  -- Clear first: memberships_one_owner_per_tenant_uidx checks each row immediately.
  update iam.memberships
  set is_owner = false,
      updated_at = now()
  where tenant_id = p_tenant_id
    and is_owner
    and user_id <> p_new_owner_user_id;

  update iam.memberships
  set is_owner = true,
      updated_at = now()
  where tenant_id = p_tenant_id
    and user_id = p_new_owner_user_id;
  perform iam._idempotency_store('tenant.ownership.transfer', 'platform', p_idempotency_key, v_fp, null);
end;
$$;

revoke all on function iam.transfer_platform_tenant_ownership(uuid, uuid, integer, text)
  from public, anon;
grant execute on function iam.transfer_platform_tenant_ownership(uuid, uuid, integer, text)
  to authenticated;
